import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
import pytest
from isgunu import is_gunu_ekle, is_gunu_farki

def test_ekle_basit_ileri():
    assert is_gunu_ekle("2026-10-26", 1, []) == "2026-10-27"

def test_ekle_baslangic_dahil_edilmez():
    # Pazartesi iş günü olsa bile sayılmaz, 2 gün sonrası Çarşamba olur
    assert is_gunu_ekle("2026-10-26", 2, []) == "2026-10-28"

def test_ekle_hafta_sonu_atlama():
    # Cuma +1 = Pazartesi
    assert is_gunu_ekle("2026-10-30", 1, []) == "2026-11-02"

def test_ekle_negatif_geri():
    assert is_gunu_ekle("2026-10-27", -1, []) == "2026-10-26"

def test_ekle_negatif_hafta_sonu_atlama():
    # Pazartesi -1 = önceki Cuma
    assert is_gunu_ekle("2026-10-26", -1, []) == "2026-10-23"

def test_ekle_sifir_is_gunu():
    assert is_gunu_ekle("2026-10-26", 0, []) == "2026-10-26"

def test_ekle_sifir_hafta_sonu_yuvarlama():
    assert is_gunu_ekle("2026-10-31", 0, []) == "2026-11-02"
    assert is_gunu_ekle("2026-11-01", 0, []) == "2026-11-02"

def test_ekle_tatil_atlama():
    assert is_gunu_ekle("2026-10-26", 1, ["2026-10-27"]) == "2026-10-28"

def test_ekle_yinelenen_tatil_bir_kez():
    assert is_gunu_ekle("2026-10-26", 1, ["2026-10-27", "2026-10-27"]) == "2026-10-28"

def test_ekle_hafta_sonuna_denk_gelen_tatil():
    assert is_gunu_ekle("2026-10-30", 1, ["2026-10-31"]) == "2026-11-02"

def test_fark_basit():
    assert is_gunu_farki("2026-10-26", "2026-10-28", []) == 2

def test_fark_bitis_haric_baslangic_dahil():
    assert is_gunu_farki("2026-10-26", "2026-10-27", []) == 1
    assert is_gunu_farki("2026-10-26", "2026-10-26", []) == 0

def test_fark_tatil_ve_hafta_sonu():
    assert is_gunu_farki("2026-10-26", "2026-10-28", ["2026-10-27"]) == 1
    assert is_gunu_farki("2026-10-30", "2026-11-02", []) == 1

def test_fark_negatif():
    assert is_gunu_farki("2026-10-28", "2026-10-26", []) == -2
    r = is_gunu_farki("2026-11-02", "2026-10-30", [])
    assert isinstance(r, int) and r < 0

def test_gecersiz_bicim_valueerror():
    with pytest.raises(ValueError):
        is_gunu_ekle("26-10-2026", 1, [])
    with pytest.raises(ValueError):
        is_gunu_ekle("2026/10/26", 1, [])
    with pytest.raises(ValueError):
        is_gunu_farki("2026-10-26", "2026-1-5", [])

def test_gecersiz_takvim_tarihi_valueerror():
    with pytest.raises(ValueError):
        is_gunu_ekle("2026-02-30", 1, [])
    with pytest.raises(ValueError):
        is_gunu_farki("2026-02-30", "2026-03-01", [])

def test_artik_gun_dogru():
    assert is_gunu_ekle("2024-02-28", 1, []) == "2024-02-29"
    assert is_gunu_farki("2024-02-28", "2024-03-01", []) == 2

def test_tatiller_liste_degilse_typeerror():
    with pytest.raises(TypeError):
        is_gunu_ekle("2026-10-26", 1, "2026-10-27")
    with pytest.raises(TypeError):
        is_gunu_farki("2026-10-26", "2026-10-28", None)

def test_tatiller_hatali_oge_typeerror():
    with pytest.raises(TypeError):
        is_gunu_ekle("2026-10-26", 1, [123])
    with pytest.raises(TypeError):
        is_gunu_farki("2026-10-26", "2026-10-28", [None])

