import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
import pytest
from urun_arama import normalize, build_index, ara

def test_normalize_kucuk_harf():
    assert normalize("KOLYE") == "kolye"
    assert normalize("Bilezik") == "bilezik"

def test_normalize_buyuk_I():
    assert normalize("I") == "ı"
    assert normalize("IŞIK") == "ışık"

def test_normalize_buyuk_noktali_I():
    assert normalize("İ") == "i"
    assert normalize("İSTANBUL") == "istanbul"

def test_normalize_noktalama():
    assert normalize("kolye,bilezik!") == "kolye bilezik"
    assert normalize("altın-kolye") == "altın kolye"

def test_normalize_coklu_bosluk():
    assert normalize("kolye   bilezik") == "kolye bilezik"
    assert normalize("  kolye  bilezik  ") == "kolye bilezik"

def test_normalize_sayisal():
    assert normalize("14 Ayar Altın") == "14 ayar altın"
    assert "14" in normalize("14 ayar").split()

def test_build_ve_ara_basit():
    urunler = {1: "altın kolye", 2: "gümüş bilezik"}
    idx = build_index(urunler)
    assert ara("kolye", idx, urunler) == [1]
    assert ara("bilezik", idx, urunler) == [2]

def test_ara_bos_sorgu():
    urunler = {1: "kolye"}
    idx = build_index(urunler)
    assert ara("", idx, urunler) == []
    assert ara("   ", idx, urunler) == []
    assert ara(",,,!!!", idx, urunler) == []

def test_ara_ve_mantigi():
    urunler = {1: "altın kolye", 2: "altın bilezik", 3: "altın kolye bilezik"}
    idx = build_index(urunler)
    assert ara("altın kolye", idx, urunler) == [1, 3]

def test_ara_siralama_frekans():
    urunler = {1: "kolye kolye bilezik", 2: "kolye bilezik"}
    idx = build_index(urunler)
    assert ara("kolye bilezik", idx, urunler) == [1, 2]
    assert ara("kolye", idx, urunler) == [1, 2]

def test_ara_siralama_esitlik_id():
    urunler = {2: "kolye", 1: "kolye", 3: "kolye"}
    idx = build_index(urunler)
    assert ara("kolye", idx, urunler) == [1, 2, 3]

def test_ara_harf_noktalama_duyarsiz():
    urunler = {1: "Altın Kolye"}
    idx = build_index(urunler)
    assert ara("KOLYE", idx, urunler) == [1]
    assert ara("kolye,", idx, urunler) == [1]
    assert ara("ALTIN KOLYE", idx, urunler) == [1]

def test_build_index_typeerror_id():
    with pytest.raises(TypeError):
        build_index({"1": "kolye"})
    with pytest.raises(TypeError):
        build_index({1.5: "kolye"})

def test_build_index_typeerror_aciklama():
    with pytest.raises(TypeError):
        build_index({1: 123})
    with pytest.raises(TypeError):
        build_index({1: None})

def test_ara_valueerror_bozuk_indeks():
    urunler = {1: "kolye"}
    with pytest.raises(ValueError):
        ara("kolye", {"kolye": [1, 2]}, urunler)
    with pytest.raises(ValueError):
        ara("kolye", "bozuk", urunler)
    with pytest.raises(ValueError):
        ara("kolye", {123: {1: 1}}, urunler)

def test_ara_bulunamayan_belirtec():
    urunler = {1: "kolye"}
    idx = build_index(urunler)
    assert ara("küpe", idx, urunler) == []
    assert ara("kolye küpe", idx, urunler) == []

import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
import pytest
from zaman_damgasi import parse_tr_tarih, gun_farki_iso

def test_parse_dd_mm_dash():
    assert parse_tr_tarih("05-01-2026 14:30") == "2026-01-05 14:30"

def test_parse_dd_mm_slash():
    assert parse_tr_tarih("05/01/2026 14:30") == "2026-01-05 14:30"

def test_parse_yyyy_mm_dd_T():
    assert parse_tr_tarih("2026-01-05T14:30") == "2026-01-05 14:30"

def test_parse_unpadded_invalid():
    with pytest.raises(ValueError):
        parse_tr_tarih("5-1-2026 14:30")

def test_parse_impossible_date():
    with pytest.raises(ValueError):
        parse_tr_tarih("2026-02-30T10:00")

def test_parse_invalid_format():
    with pytest.raises(ValueError):
        parse_tr_tarih("2026-01-05 14:30")

def test_parse_equality_across_formats():
    a = parse_tr_tarih("05-01-2026 14:30")
    b = parse_tr_tarih("05/01/2026 14:30")
    c = parse_tr_tarih("2026-01-05T14:30")
    assert a == b == c == "2026-01-05 14:30"
    d = parse_tr_tarih("06-01-2026 14:30")
    assert a != d

def test_parse_leap_valid():
    assert parse_tr_tarih("29-02-2024 12:00") == "2024-02-29 12:00"

def test_parse_nonleap_invalid():
    with pytest.raises(ValueError):
        parse_tr_tarih("29-02-2023 12:00")

def test_parse_type_error():
    with pytest.raises(TypeError):
        parse_tr_tarih(None)
    with pytest.raises(TypeError):
        parse_tr_tarih(123)

def test_gun_farki_zero():
    assert gun_farki_iso("2026-01-05 14:30", "2026-01-05 14:30") == 0

def test_gun_farki_negative_positive():
    assert gun_farki_iso("2026-01-06 14:30", "2026-01-05 14:30") == -1
    assert gun_farki_iso("2026-01-05 14:30", "2026-01-06 14:30") == 1

def test_gun_farki_23h59_zero():
    assert gun_farki_iso("2026-01-05 00:00", "2026-01-05 23:59") == 0

def test_gun_farki_23h59_zero_negative():
    assert gun_farki_iso("2026-01-05 23:59", "2026-01-05 00:00") == 0

def test_gun_farki_half_hour_truncated():
    assert gun_farki_iso("2026-01-05 00:00", "2026-01-06 00:30") == 1

def test_gun_farki_half_hour_truncated_negative():
    assert gun_farki_iso("2026-01-06 00:30", "2026-01-05 00:00") == -1

def test_gun_farki_rejects_non_iso():
    with pytest.raises(ValueError):
        gun_farki_iso("05-01-2026 14:30", "2026-01-05 14:30")
    with pytest.raises(ValueError):
        gun_farki_iso("2026-01-05 14:30", "2026-01-05T14:30")

def test_gun_farki_type_error():
    with pytest.raises(TypeError):
        gun_farki_iso(None, "2026-01-05 14:30")
    with pytest.raises(TypeError):
        gun_farki_iso("2026-01-05 14:30", 123)

import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
from istatistik import MetinAnalizci
import pytest

def test_bos_metin_harf():
    assert MetinAnalizci("").harf_say() == {}

def test_bos_metin_kelime():
    assert MetinAnalizci("").kelime_say() == 0

def test_str_olmayan_int():
    with pytest.raises(TypeError):
        MetinAnalizci(123)

def test_str_olmayan_none():
    with pytest.raises(TypeError):
        MetinAnalizci(None)

def test_uzun_metin_valueerror():
    with pytest.raises(ValueError):
        MetinAnalizci("a" * 100001)

def test_sinir_100000_kabul():
    m = MetinAnalizci("a" * 100000)
    assert m.harf_say() == {"a": 100000}

def test_harf_temel():
    assert MetinAnalizci("aaa").harf_say() == {"a": 3}

def test_harf_buyuk_kucuk_farksiz():
    assert MetinAnalizci("AaAa").harf_say() == {"a": 4}
    assert MetinAnalizci("Çç").harf_say() == {"ç": 2}

def test_harf_I_ile_ı_ayni():
    assert MetinAnalizci("Iı").harf_say() == {"ı": 2}
    assert MetinAnalizci("III").harf_say() == {"ı": 3}

def test_harf_İ_ile_i_ayni():
    assert MetinAnalizci("İi").harf_say() == {"i": 2}
    assert MetinAnalizci("İİİ").harf_say() == {"i": 3}

def test_harf_sadece_turkce():
    d = MetinAnalizci("a1! b2?").harf_say()
    assert d == {"a": 1, "b": 1}

def test_harf_turkce_siralama():
    d = MetinAnalizci("şçğabc").harf_say()
    assert list(d.keys()) == ["a", "b", "c", "ç", "ğ", "ş"]
    d2 = MetinAnalizci("ÜuÖo").harf_say()
    assert list(d2.keys()) == ["o", "ö", "u", "ü"]

def test_kelime_temel():
    assert MetinAnalizci("merhaba dünya").kelime_say() == 2
    assert MetinAnalizci("tek").kelime_say() == 1

def test_kelime_sayi_parcalari_sayilmaz():
    assert MetinAnalizci("123 456").kelime_say() == 0
    assert MetinAnalizci("abc 123").kelime_say() == 1

def test_kelime_noktalama_bolmez():
    assert MetinAnalizci("merhaba,dünya").kelime_say() == 1
    assert MetinAnalizci("merhaba,dünya selam").kelime_say() == 2

def test_kelime_harf_iceren_karisik():
    assert MetinAnalizci("abc123 !!!").kelime_say() == 1
    assert MetinAnalizci("!!! ???").kelime_say() == 0

def test_kelime_aralik_ve_bosluk():
    assert MetinAnalizci("   \n\t  ").kelime_say() == 0
    s = MetinAnalizci("a b\nc\td").kelime_say()
    assert s == 4
    assert 0 <= s <= 20000
